(function(){'use strict';function r(f){document.readyState==='loading'?document.addEventListener('DOMContentLoaded',f,{once:true}):f()}r(function(){var shell=document.querySelector('.dashboard-shell');if(!shell)return;document.body.classList.add('fqx-v122-admin-visible');var btn=shell.querySelector('.mq-sidebar-toggle'),side=shell.querySelector('.sidebar'),ov=shell.querySelector('.mq-sidebar-overlay');function open(v){shell.classList.toggle('sidebar-open',!!v);document.body.classList.toggle('sidebar-open',!!v);if(side)side.classList.toggle('open',!!v)}if(btn&&!btn.dataset.v122){btn.dataset.v122='1';btn.addEventListener('click',function(e){e.preventDefault();open(!shell.classList.contains('sidebar-open'))})}if(ov){ov.addEventListener('click',function(){open(false)})}shell.querySelectorAll('.sidebar .nav-item').forEach(function(a){a.addEventListener('click',function(){open(false)})});});})();
